  if(!raw)return 'Something went wrong. Nothing was changed.';
  const probe=[raw,error?.code,error?.details].filter(Boolean).join(' ');
  for(const rule of OWNER_ERROR_NOISE_RULES_V170)if(rule[0].test(probe))return rule[1];
