function mobileSearchShellHtml(){
  const canFindCustomer=canReadModule('clients')||canReadModule('till');
  if(!canFindCustomer)return '';
  return `<button type="button" class="mobile-search-trigger" id="mobileSearchOpen" aria-label="Find customer">${CUI.icon('search',{size:19})}</button>
    <div class="mobile-search-sheet" id="mobileSearchSheet" aria-modal="true" role="dialog" aria-labelledby="mobileSearchTitle">
      <div class="mobile-search-panel">
        <div class="row"><div><b id="mobileSearchTitle">Find customer</b><p class="muted small">Search by name or phone number.</p></div><span class="spacer"></span><button type="button" class="btn ghost sm" id="mobileSearchClose">Close</button></div>
        <label class="sr-only" for="mobileSearchInput">Customer search</label>
        <div class="global-search" role="search" style="margin-top:12px;max-width:none;flex:1 1 auto">
          <span class="global-search-ic">${CUI.icon('search',{size:17})}</span>
          <input id="mobileSearchInput" type="search" autocomplete="off" enterkeyhint="search" placeholder="Name or phone number">
          <button type="button" class="global-search-go" id="mobileSearchGo" aria-label="Search customers">${CUI.icon('forward',{size:16})}</button>
        </div>
      </div>
    </div>`;
}
function runWorkspaceCustomerLookup(query){
  const q=String(query||'').trim();
  if(!q)return false;
  const digits=q.replace(/\D/g,'');
  const looksPhone=digits.length>=4&&/^[+\s()\-\d]+$/.test(q);
  const goTo=target=>{if(location.hash===target){route()}else{nav(target)}};
  if(looksPhone&&canReadModule('till')){pendingTillPhone=digits;goTo('#/till');return true}
  if(canReadModule('clients')){pendingCustomerSearch=q;goTo('#/clients');return true}
  if(canReadModule('till')){pendingTillPhone=digits;goTo('#/till');return true}
  return false;
}
function wireMobileSearchShell(){
  const open=$('mobileSearchOpen'),sheet=$('mobileSearchSheet'),close=$('mobileSearchClose'),input=$('mobileSearchInput'),go=$('mobileSearchGo');
  if(!open||!sheet||!input)return;
  const show=()=>{sheet.setAttribute('open','');requestAnimationFrame(()=>input.focus({preventScroll:true}))};
  const hide=()=>sheet.removeAttribute('open');
  const run=()=>{if(runWorkspaceCustomerLookup(input.value)){input.value='';hide()}};
  open.onclick=show;close&&(close.onclick=hide);go&&(go.onclick=run);
  sheet.addEventListener('click',event=>{if(event.target===sheet)hide()});
  input.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();run()}else if(e.key==='Escape'){e.preventDefault();hide()}};
}
function wireGlobalActions(){
  const input=$('globalSearch');
  if(input){
    /* Route the query into an EXISTING lookup — a phone-shaped term to Record sale's phone lookup,
       otherwise a name to the Customers search — so no new database query is introduced. When the
       target route is already open, re-run route() directly (setting the hash to its current value
       fires no hashchange). */
    const run=()=>{
      const q=input.value.trim();
      if(!q)return;
      if(runWorkspaceCustomerLookup(q))input.value='';
    };
    input.onkeydown=e=>{
      if(e.key==='Enter'){e.preventDefault();run()}
      else if(e.key==='Escape'){e.preventDefault();input.value='';input.blur()}
    };
    const go=$('globalSearchGo');if(go)go.onclick=run;
  }
  const qe=$('globalQuickEarn');if(qe)qe.onclick=()=>nav('#/till');
  const na=$('globalNewAppt');if(na)na.onclick=()=>{
    /* Only ask for the form when this user may actually book; otherwise the button is the
       "View calendar" affordance and must stay one. canWriteModule is re-read here rather than
       reused from globalActionsHtml, whose `canNewAppt` is scoped to that function. */
    pendingOpenApptFormV217=canWriteModule('appointments');
    nav('#/appointments');
    if(location.hash==='#/appointments')route();
  };
}
function userDisplayNameV158(){
  const meta=S.user?.user_metadata||{};
  return String(meta.full_name||meta.name||meta.given_name||'').trim();
}
function profileBranchScopeLabelV158(){
  if(!selectedBranchId)return 'All branches';
  const option=[...document.querySelectorAll('#profileBranchScopeSelectV158 option')].find(candidate=>candidate.value===selectedBranchId);
  return String(option?.textContent||'Selected branch');
}
async function hydrateProfileBranchSelectorV158(page){
  const mount=$('profileBranchScopeV158');
  if(!mount)return;
  mount.innerHTML='<span class="branch-loading-pill" aria-live="polite">Branch scope</span>';
  try{
    const {isAdmin,branches}=await visibleBranchesForCurrentUser();
    if(!$('profileBranchScopeV158'))return;
    /* V217: only an ACTIVE branch can be a reporting scope — the server refuses any other, so
       offering one here produced a workspace that could not load its own dashboard or customer
       list. V224 removed the "awaiting payment" pill the owner struck out of the top bar; the
       branch and its reason are still stated on the Branches page, which is where it is acted on. */
    const allowed=activeBranchesForScopeV217(branches);
    if(selectedBranchId&&!allowed.some(branch=>branch.id===selectedBranchId)){
      selectedBranchId=isAdmin?null:(allowed[0]?.id||null);
    }
    mount.innerHTML=(allowed.length||isAdmin)
      ?`<span class="topbar-branch-label-v210" aria-hidden="true">Viewing</span>
        <select id="profileBranchScopeSelectV158" aria-label="View data for branch" title="This changes the workspace view. Operational actions still use one selected branch.">
          ${isAdmin?'<option value="">All branches</option>':''}
          ${allowed.map(branch=>`<option value="${branch.id}">${esc(branch.name)}</option>`).join('')}
        </select>
        `
      :'<span class="muted small">No branch assigned</span>';
    const select=$('profileBranchScopeSelectV158');
    if(select){
      select.value=selectedBranchId||'';
      select.onchange=()=>{
        selectedBranchId=select.value||null;
        profileOpen=false;
        renderShell(page);
        route();
      };
    }
  }catch(error){
    console.error(error);
    if($('profileBranchScopeV158'))$('profileBranchScopeV158').innerHTML='<span class="err small">Branch list unavailable.</span>';
  }
}
/* Owner ruling 2026-07-18: the firm profile lives TOP-RIGHT, not bottom-left.
   It now sits in a sticky frosted .appbar in the right-hand column, so it stays put
   while the page scrolls (native-app behaviour) and its menu drops downward. */
function profileHtml(){
  const displayName=userDisplayNameV158();
  return `<div class="profile" id="profwrap">
      <!-- V225: the owner struck the business name and industry out of the top bar. The avatar
           initial still identifies the workspace visually, but a lone initial is not an
           accessible name, so the button carries one and the full name moves inside the menu. -->
      <button type="button" class="who" id="profWho" aria-haspopup="true" aria-expanded="${profileOpen}" aria-controls="profmenu" ${workspaceTemplateAttributeV97('aria-label','accountMenuForBusiness',{business:S.biz.name||'Workspace'})}>
        <div class="avatar" aria-hidden="true">${esc((S.biz.name||'?').trim().charAt(0).toUpperCase())}</div>
        <span class="chev" aria-hidden="true">${profileOpen?'−':'+'}</span>
      </button>
      ${profileOpen?`<div class="menu" id="profmenu" aria-label="Account links">
        <div class="profile-menu-section" style="overflow-wrap:anywhere"><b data-merchant-content style="display:block">${esc(S.biz.name)}</b><span data-merchant-content class="small muted">${esc(INDUSTRIES[S.biz.industry]?.label||S.biz.industry||'')}</span></div>
        <div class="profile-menu-section small muted" style="overflow-wrap:anywhere">Signed in as<br><b style="color:var(--ink)">${esc(displayName||S.user?.email||'User')}</b>${displayName&&S.user?.email?`<br><span>${esc(S.user.email)}</span>`:''}</div>
        <!-- V225 (owner: "put inside here" pointing from the top-bar language select to the
             profile menu). Language is a personal preference set once, not a per-task control,
             so it belongs with the other account settings rather than beside Record sale. -->
        <div class="profile-menu-section">${workspaceLanguagePickerV97()}</div>
        <form class="profile-menu-section" id="profileNameFormV158">
          <label for="profileDisplayNameV158">Your display name</label>
          <div class="row"><input id="profileDisplayNameV158" autocomplete="name" maxlength="120" value="${esc(displayName)}" placeholder="e.g. Chuan Seng"><button class="btn ghost sm" type="submit">Save</button></div>
          <div class="profile-menu-saved" id="profileNameStatusV158" aria-live="polite"></div>
        </form>
        <!-- V210 (owner annotation: "move out to outside here at upper right and fixed all the
             way"). The branch scope decides what every number on the screen MEANS, so burying it
             two taps inside an account menu meant an owner could read a dashboard without seeing
             which branch it was for. It now lives in the top bar, always visible. -->
        <!-- The picker moved to the top bar, but the top bar hides it under 900px where space
             runs out. So the menu still states WHICH branch is in view on a phone — the scope
             must never be invisible, only relocated. -->
        <div class="profile-menu-section profile-branch-readout-v210">
          <label>Viewing data for</label>
          <div class="muted small">${esc(profileBranchScopeLabelV158())}</div>
        </div>
        ${S.hasCustomerPersona?`<a href="#/wallet" id="pmWallet">${CUI.icon('wallet',{size:18})}${esc(BRAND.customerLabel)}</a>`:''}
        ${S.myRole==='owner'?`<a href="#/setup" id="pmSetup">${CUI.icon('setup',{size:18})}Get started</a>`:''}
        ${S.myRole==='owner'?`<a href="#/settings" id="pmSettings">${CUI.icon('settings',{size:18})}Settings</a>`:''}
        <!-- V209 (owner annotations): "remove this" on Team & staff — Staff Members is already in
             the sidebar, and two doors to one page is the duplicated navigation flagged at V180.
             "move here" on Branches — it belongs in Operations setup beside Staff and Services,
             not in the account menu, so it moved to the sidebar and left here. -->
        ${S.isSA?`<a href="#/platform" id="pmPlatform">${CUI.icon('platform',{size:18})}Platform</a>`:''}
        <a href="/data-request.html" id="pmDeleteAccount">${CUI.icon('back',{size:18})}Account &amp; privacy</a>
        <a href="#" id="pmSignout" style="color:var(--red)">${CUI.icon('back',{size:18})}Sign out</a>
      </div>`:''}
    </div>`;
}
/* Opening/closing the profile menu must NOT touch #main or #navwrap — it used to call
   renderShell(page), which also re-invokes the current page's render function (full
   Supabase refetch, chart re-animation, any custom date range reset). This widget now
   re-renders only itself. */
function wireProfile(page){
  $('profWho').onclick=(e)=>{e.stopPropagation();profileOpen=!profileOpen;if(profileOpen){bellOpen=false;renderBell(page);}renderProfile(page);};
  /* V219. Owner: "i need a drop down in the header to select which branch they want to view now".
     V210 moved this selector OUT of the profile menu and into the top bar, but left its
     hydration inside `if(profileOpen)`. The mount div was rendered on every page and filled on
     none of them, so the header carried an invisible empty box. It is populated whenever the
     shell is wired, which is what the top-bar position always meant. */
  hydrateProfileBranchSelectorV158(page);
  if(profileOpen){
    const menu=$('profmenu');
    menu.onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();profileOpen=false;renderProfile(page);$('profWho')?.focus()}};
    const profileNameForm=$('profileNameFormV158');
    if(profileNameForm)profileNameForm.onsubmit=async(e)=>{
      e.preventDefault();
      const input=$('profileDisplayNameV158'),status=$('profileNameStatusV158');
      const name=String(input?.value||'').trim();
      if(name.length<2){if(status)status.textContent='Enter your name.';return;}
      const button=profileNameForm.querySelector('button[type="submit"]');
      CUI.setButtonBusy(button,{busy:true,label:'Saving…'});
      try{
        const {data,error}=await sb.auth.updateUser({data:{full_name:name,name}});
        if(error)throw error;
        if(data?.user)S.user=data.user;
        else S.user={...S.user,user_metadata:{...(S.user?.user_metadata||{}),full_name:name,name}};
        await sb.from('staff').update({full_name:name}).eq('business_id',S.biz.id).eq('user_id',S.user.id);
        if(status)status.textContent='Name saved.';
        renderProfile(page);
      }catch(error){
        console.error(error);
        if(status)status.textContent='Name could not be saved.';
      }finally{
        CUI.setButtonBusy(button,{busy:false});
      }
    };
    $('pmSignout').onclick=async(e)=>{e.preventDefault();killChannels();await sb.auth.signOut({scope:'local'});resetClientSessionState();nav('#/')};
    const pmSetup=$('pmSetup');if(pmSetup)pmSetup.onclick=()=>{profileOpen=false};
    const pmS=$('pmSettings');if(pmS) pmS.onclick=()=>{profileOpen=false};
    const pmT=$('pmTeam');if(pmT) pmT.onclick=()=>{profileOpen=false};
    const pmP=$('pmPlatform');if(pmP) pmP.onclick=()=>{profileOpen=false};
    const pmW=$('pmWallet');if(pmW) pmW.onclick=()=>{profileOpen=false};
    /* v188: the profile menu links to the data-request page instead of opening a self-service
       deletion dialog; closing an account goes through Peekaa. */
    const pmD=$('pmDeleteAccount');if(pmD)pmD.onclick=()=>{profileOpen=false};
    /* click-away to dismiss — expected of a native popover, and without it the menu
       could only be closed by re-clicking the chip. One-shot listener, re-armed on
       each open, so it can't stack up across renders. */
    setTimeout(()=>document.addEventListener('click',function away(ev){
      const w=$('profwrap');
      if(w&&!w.contains(ev.target)){profileOpen=false;document.removeEventListener('click',away);renderProfile(page);}
      else if(!w){document.removeEventListener('click',away);}
    }),0);
  }
}
function renderProfile(page){
  const wrap=$('profwrap');
  if(!wrap) return;
  wrap.outerHTML=profileHtml();
  wireProfile(page);
}

/* ---------- realtime notifications (bell, left of the profile chip) ----------
   One realtime channel per signed-in session, built once against the current S.biz and
   reused across every route change (route() -> renderShell() -> initNotifications() runs
   on every navigation, but ensureRealtimeChannel() is a no-op once a channel for this
   business already exists — tearing it down and rebuilding on every route change would be
   wasteful and could miss events landing in the gap). killChannels() is the only thing that
   removes it, called on sign-out (mirrors killCharts()). */
function timeAgo(iso){
  if(!iso) return '';
  const s=Math.max(0,(Date.now()-new Date(iso).getTime())/1000);
  if(s<60) return 'just now';
  if(s<3600) return Math.floor(s/60)+'m ago';
  if(s<86400) return Math.floor(s/3600)+'h ago';
  return Math.floor(s/86400)+'d ago';
}
/* Every notification kind we currently emit routes to the same place — booking requests,
   waitlist and change-request activity are all triaged from the Bookings page. Kept as an
   explicit map (not a blanket default) so a future new kind is a deliberate decision, not
   an accident. */
/* V171: '#/home' and '#/customers' were never real routes (the router keys are 'dashboard'
   and 'clients'), so these two notification kinds silently dumped the owner on the Dashboard.
   Payment-due now opens Settings (billing lives in Modules & plan); feedback opens Customers,
   where the Visit feedback queue actually renders. */
const NOTIF_ROUTE={booking_new:'#/bookings',booking_waitlisted:'#/bookings',change_request:'#/bookings',
  booking_expired:'#/bookings',waitlist_ready:'#/bookings',subscription_payment_due:'#/settings',
  feedback_new:'#/clients'};
async function loadNotifications(){
  const {data,error}=await sb.rpc('get_notifications',{p_business:S.biz.id,p_limit:30});
  if(error){notifError=error.message||'Could not load notifications';return}
  notifError=null;notifLoaded=true;notifState={unread:data.unread||0,items:data.items||[]};
}
function bellHtml(){
  const n=notifState.unread||0;
  return `<div class="bellwrap" id="bellwrap">
      <button type="button" class="bellbtn" id="bellBtn" title="Notifications" ${n?workspaceTemplateAttributeV97('aria-label','notificationsUnread',{count:n}):'aria-label="Notifications"'} aria-haspopup="true" aria-expanded="${bellOpen}">${CUI.icon('bell',{size:19})}${n>0?`<span class="dot" aria-hidden="true">${n>99?'99+':n}</span>`:''}</button>
      ${bellOpen?notifMenuHtml():''}
    </div>`;
}
function notifMenuHtml(){
  const items=notifState.items||[];
  const isOwner=S.myRole==='owner';
  return `<div class="notif-menu" id="notifmenu">
    <div class="row" style="padding:4px 8px 8px"><b class="small">Notifications</b><span class="spacer"></span>
      ${notifState.unread>0?`<button class="btn ghost sm" id="markAll" style="padding:4px 10px;font-size:11.5px">Mark all read</button>`:''}</div>
    ${notifError?`<div class="err" style="margin:0 6px 8px">${esc(notifError)}</div>`:''}
    ${!notifLoaded?`<div class="notif-empty">Loading…</div>`
      :items.length?items.map(it=>`<button type="button" class="notif-item ${it.read_at?'':'unread'}" data-nid="${esc(it.id)}" data-ref="${esc(it.kind)}" data-refid="${esc(it.ref_id||'')}">
          <div class="t">${esc(it.title||'')}</div>
          ${it.body?`<div class="b">${esc(it.body)}</div>`:''}
          <div class="ago">${timeAgo(it.created_at)}</div></button>`).join('')
      :`<div class="notif-empty">No notifications yet.</div>`}
    <hr style="border:none;border-top:1px solid var(--hair);margin:6px 0">
    ${isOwner?`<div class="switchrow"><span>Pop-up alerts</span>
        <button type="button" class="tglsw ${S.biz.notify_new_bookings?'on':''}" id="notifToggle" aria-label="Toggle pop-up alerts" aria-pressed="${!!S.biz.notify_new_bookings}"></button></div>`
      :`<div class="switchrow"><span>Pop-up alerts (this session)</span>
        <button type="button" class="tglsw ${muteAlerts?'':'on'}" id="notifToggle" aria-label="Toggle pop-up alerts for this session" aria-pressed="${!muteAlerts}"></button></div>`}
    </div>`;
}
function wireBell(page){
  $('bellBtn').onclick=(e)=>{e.stopPropagation();bellOpen=!bellOpen;if(bellOpen){profileOpen=false;renderProfile(page);}renderBell(page);};
  if(!bellOpen) return;
  const markAll=$('markAll');
  if(markAll) markAll.onclick=async(e)=>{
    e.stopPropagation();markAll.disabled=true;
    const {error}=await sb.rpc('mark_all_notifications_read',{p_business:S.biz.id});
    if(error){fail(error);markAll.disabled=false;return}
    notifState.items=(notifState.items||[]).map(it=>({...it,read_at:it.read_at||new Date().toISOString()}));
    notifState.unread=0;
    renderBell(page);
  };
  document.querySelectorAll('.notif-item').forEach(el=>el.onclick=async()=>{
    const id=el.dataset.nid,kind=el.dataset.ref;
    const {error}=await sb.rpc('mark_notification_read',{p_id:id});
    if(!error){
      const item=(notifState.items||[]).find(i=>i.id===id);
      if(item&&!item.read_at){item.read_at=new Date().toISOString();notifState.unread=Math.max(0,notifState.unread-1);}
    }
    bellOpen=false;
    /* V206 (owner: "clicking in the specific notification should brings me to the specific page
       to approve or reject or call customer"). notifications already carried ref_table/ref_id —
       the exact record — and the panel was throwing it away and landing you on the list to hunt
       for the row you had just been told about. */
    pendingNotificationFocusV206=el.dataset.refid||'';
    nav(NOTIF_ROUTE[kind]||'#/bookings');
  });
  const tgl=$('notifToggle');
  if(tgl) tgl.onclick=async(e)=>{
    e.stopPropagation();
    if(S.myRole==='owner'){
      const to=!S.biz.notify_new_bookings;
      tgl.style.pointerEvents='none';
      const {error}=await sb.rpc('set_booking_settings',{p_business:S.biz.id,
        p_hold_minutes:S.biz.booking_hold_minutes,p_overflow:S.biz.booking_overflow,
        p_notify:to,p_auto_confirm:S.biz.booking_auto_confirm});
      if(error){fail(error);tgl.style.pointerEvents='';return}
      S.biz.notify_new_bookings=to;
    }else{
      muteAlerts=!muteAlerts;
    }
    renderBell(page);
  };
  /* click-away, same one-shot pattern as the profile menu */
  setTimeout(()=>document.addEventListener('click',function away(ev){
    const w=$('bellwrap');
    if(w&&!w.contains(ev.target)){bellOpen=false;document.removeEventListener('click',away);renderBell(page);}
    else if(!w){document.removeEventListener('click',away);}
  }),0);
}
function renderBell(page){
  const wrap=$('bellwrap');
  if(!wrap) return;
  wrap.outerHTML=bellHtml();
  wireBell(page);
}
/* Re-runs the currently-open page's own render fn (no hash change) so new booking activity
   shows up without the owner having to manually refresh — the #1 complaint this feature set
   is meant to fix. Only wired for the pages where booking/waitlist activity is visible. */
function autoRefreshIfRelevant(){
  const key=(currentPage&&currentPage[0])||'';
  /* V171: the old 'customers' entry was dead — the router's key for that screen is 'clients',
     so it never matched. It is deliberately NOT fixed to 'clients': these events are booking/
     appointment inserts, and re-rendering the Customers page on them would wipe an open
     Add/Edit-customer form mid-typing. Customers refreshes on navigation instead. */
  const P={bookings:bookingsPage,appointments:appointmentsPage,waitlist:waitlistPage};
  if(P[key]) P[key](currentPage[1]);
}
function ensureRealtimeChannel(){
  if(rtChannel&&rtChannelBizId===S.biz.id) return; // already live for this business — reuse it
  if(rtChannel){ try{sb.removeChannel(rtChannel);}catch(e){} rtChannel=null; }
  rtChannel=sb.channel('rt-'+S.biz.id)
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'notifications',filter:'business_id=eq.'+S.biz.id},payload=>{
      notifState.unread=(notifState.unread||0)+1;
      notifState.items=[payload.new,...(notifState.items||[])].slice(0,30);
      renderBell(currentPage);
      autoRefreshIfRelevant();
      if(S.biz.notify_new_bookings&&!muteAlerts) toast('🔔 '+(payload.new?.title||'New notification'));
    })
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'booking_requests',filter:'business_id=eq.'+S.biz.id},()=>autoRefreshIfRelevant())
    .on('postgres_changes',{event:'INSERT',schema:'public',table:'appointments',filter:'business_id=eq.'+S.biz.id},()=>autoRefreshIfRelevant())
    .subscribe();
  rtChannelBizId=S.biz.id;
}
function killChannels(){
  if(rtChannel){ try{sb.removeChannel(rtChannel);}catch(e){} }
  rtChannel=null;rtChannelBizId=null;
}
async function initNotifications(){
  if(!S.biz) return;
  await loadNotifications();
  renderBell(currentPage);
  ensureRealtimeChannel();
}

