  const loyaltySelectionForModeV240=mode=>mode==='tiers'?'tiers':mode==='both'?'both':'redeem';
  const loyaltySelectionV230=model==='stamps'?'stamps':loyaltySelectionForModeV240(loyaltyModeV230);
