    const basis=$('ltb')?.value||p?.tier_basis||'visits';
    const status=$('trDefaultsStatus');
    const slot=`peekaa.loyalty.recommended-tiers.v148.${S.biz.id}`;
    const fingerprint=JSON.stringify({business:S.biz.id,version:draftVersionId||null,basis,hash:draftSnapshotHash||null});
    const idempotencyKey=writeAttemptKey(slot,fingerprint);
    defaults.disabled=true;defaults.textContent='Creating tier drafts…';
